package io.dndroll.domain;

import static org.junit.jupiter.api.Assertions.*;
import io.dndroll.domain.CharacterSheet.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class ContentEntryTest {
    @Test void exportedFillCarriesOpenAttributionAndModificationNotice(){var e=entry("FEATURE");var open=new ContentEntry(e.id(),e.data(),true,"CC-BY-4.0","Wizards of the Coast LLC; https://creativecommons.org/licenses/by/4.0/legalcode","中文概括与结构化提取");var filled=open.fill(CharacterSheet.empty("Hero"),"STR","");var source=filled.features().getFirst().source().detail();assertTrue(source.contains(open.attribution()));assertTrue(source.contains(open.changes()));}
    ContentEntry entry(String type){return new ContentEntry(UUID.randomUUID(),new ContentEntry.Data("测试",List.of("Alias"),type,new Source("原创","rev-2026","CUSTOM","选择说明"),"只供人工解释",0,"1d4","穿刺","本团可共享"),false,"CAMPAIGN","原创声明","不自动执行");}
    @Test void attackFillsOnlyChosenFieldsAndDoesNotGrantProficiencyMasteryOrSpendResources(){var s=CharacterSheet.empty("Hero");var e=entry("ATTACK");var n=e.fill(s,"DEX","");assertEquals("DEX",n.attacks().getFirst().ability());assertFalse(n.attacks().getFirst().proficient());assertEquals("",n.attacks().getFirst().mastery());assertEquals(s.combat(),n.combat());assertEquals(s.resources(),n.resources());assertEquals(s.skills(),n.skills());assertTrue(n.attacks().getFirst().source().detail().contains(e.id().toString()));assertTrue(s.attacks().isEmpty());assertThrows(DomainException.class,()->e.fill(n,"DEX",""));}
    @Test void speciesAndBackgroundReplaceDescriptionsWithoutChangingChoicesOrScores(){var s=CharacterSheet.empty("Hero");var species=entry("SPECIES").fill(s,"STR","");assertEquals("测试",species.species().name());assertEquals(s.abilities(),species.abilities());assertEquals(s.combat(),species.combat());var background=entry("BACKGROUND").fill(s,"STR","");assertEquals(s.background().increases(),background.background().increases());assertEquals(s.background().originFeat(),background.background().originFeat());assertEquals(s.abilities(),background.abilities());}
    @Test void spellRequiresRealCastingAssociationAndNeverPreparesItself(){var s=CharacterSheet.empty("Hero");var e=entry("SPELL");assertThrows(DomainException.class,()->e.fill(s,"STR","missing"));var n=new CharacterSheet(s.name(),s.avatar(),s.species(),s.background(),s.classes(),s.abilities(),s.skills(),s.saves(),s.combat(),s.attacks(),List.of(new Casting("wizard","Wizard","INT",0,0,CharacterSheet.manual())),s.spells(),s.features(),s.resources(),s.equipment(),s.money(),s.conditions(),s.modifiers(),s.overrides(),s.notes());var result=e.fill(n,"STR","wizard");assertEquals("wizard",result.spells().getFirst().castingId());assertFalse(result.spells().getFirst().prepared());assertEquals(0,result.spells().getFirst().level());}
    @Test void itemAndTextAreIndependentNonExecutableDescriptions(){var s=CharacterSheet.empty("Hero");var item=entry("ITEM").fill(s,"STR","");assertFalse(item.equipment().getFirst().equipped());assertTrue(item.attacks().isEmpty());var rule=entry("RULE").fill(s,"STR","");assertEquals("RULE",rule.features().getFirst().kind());assertEquals("只供人工解释",rule.features().getFirst().description());assertTrue(rule.resources().isEmpty());}
}
